INSERT INTO questions (job_model_id,q_type,question_text,question_data,image_path,points,order_index,id,created_at) VALUES
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','single_choice','امامك عداد وبه قراءة 65379287 أي من الأرقام التالية يجب عليه كتابته في دفتره بدون أي لغبطة؟','{"options": ["65379287", "653,792,87", "6,5,3,7,9,2,8,7", "6.5.3.7.9.2.8.7"], "correct_indices": [0]}',NULL,2.0,1,'a280a9d9-e816-4ebf-a571-4ed3bddf1c2e','2026-08-30 14:57:40.009308'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','single_choice','مواطن كانت فاتورته 170 جنيه، وأعطاك ورقتين من فئة المائة جنيه. كم جنيهاً يجب عليك أن ترده للمواطن كباقي؟','{"options": ["ورقتين فئة 10 جنيها وورقة فئة 20جنيه", "ورقتين فئة 20 جنيه", "خمس ورقات فئة 5 جنيه و خمس جنيهات", "ثلاث ورقات فئة 5 جنيه وورقة فئة 10 جنيه"], "correct_indices": [2]}',NULL,3.0,2,'f5b4d036-6541-4975-b4ed-d37d82d77dc2','2026-08-30 14:57:40.009313'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','single_choice','طُلِب منك إدخال اسم العميل التالي في النظام: "مصطفى عبد الرحمن عبد الجواد". أي من الخيارات التالية كُتِب','{"options": ["مصطفي عبدالرحمن عبد الجواد", "مصطفى عبد الرحمن عبد الجواد", "مصطفى عبدالرحمن عبدالجواد", "مصطفي عبد الرحمن عبد الجود"], "correct_indices": [1]}',NULL,2.0,1,'12cec6c6-1bc3-48dc-8707-7f8f674e45c9','2026-08-30 14:57:40.009317'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','single_choice','إذا كان الرقم القومي الصحيح للموظف في المستند الورقي هو (29508150102345)، وقام النظام بقراءته بشكل آلي. أي الخيارات التالية يحتوي على إدخال صحيح 100%؟','{"options": ["29508150102435", "29508050102345", "29508150102345 ", "29508151102345"], "correct_indices": [2]}',NULL,2.0,2,'8681182f-d184-435f-9dc3-2e1f1be85005','2026-08-30 14:57:40.009322'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','single_choice','ثناء قيامك بإدخال بيانات جدول كبير على برنامج إكسل (Excel)، انقطعت الكهرباء فجأة وتوقف الجهاز. ما هو التصرف الإداري الصحيح لتجنب حدوث هذا الموقف وضياع البيانات مستقبلاً؟','{"options": ["كتابة البيانات بسرعة أكبر بدون مراجعة", "تفعيل ميزة \"الحفظ التلقائي\" (AutoSave) والضغط المستمر على اختصار الحفظ Ctrl + S أثناء العمل. ", "الانتظار حتى نهاية اليوم لحفظ الملف بالكامل مرة واحدة", "ترك العمل على الكمبيوتر والعودة للكتابة الورقية"], "correct_indices": [1]}',NULL,1.0,0,'d6983ddf-a97e-4784-bbc9-317143832682','2026-09-02 18:00:16.170711'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','multiple_choice','طُلب منك إعداد تقرير رسمي للشركة وتنسيقه بشكل مريح للعين ومنظم قبل تسليمه للمدير. اختر كل التنسيقات الصحيحة التي يجب عليك تطبيقها:','{"options": ["توحيد نوع الخط وحجمه في جميع العناوين الرئيسية", "تلوين كل سطر في التقرير بلون مختلف لجذب الانتباه", "ترك مسافات (هوامش) متساوية ومنظمة بين الفقرات", "كتابة التقرير بالكامل بدون أي نقاط أو فواصل بين الجمل"], "correct_indices": [0, 2]}',NULL,1.0,0,'148aa0c2-fbd6-43da-a0bf-413a755e5be4','2026-09-02 18:01:18.170355'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','multiple_choice','لزيادة سرعتك وإنتاجيتك في إدخال البيانات وتجنب الاستخدام المتكرر للفأرة (الماوس)، اختر كل الاختصارات الصحيحة التي تؤدي وظيفتها بدقة','{"options": ["الضغط على Ctrl + C لنسخ النص المحدد", "الضغط على Ctrl + V للصق النص الذي تم نسخه", "الضغط على Alt + F4 لحفظ الملف الحالي بأمان", "الضغط على زر Space (المسطرة) للتنقل بين خلايا الإكسل للأسفل"], "correct_indices": [0, 1]}',NULL,1.0,0,'8e16a069-263a-4717-b376-3829a503465c','2026-09-02 18:01:57.569590'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','multiple_choice','أثناء قيامك بنقل بيانات العملاء من استمارات ورقية قديمة إلى النظام، وجدت استمارة ورقية بها اسم العميل غير واضح (خط اليد سيء جداً) ورقم هاتفه ناقص رقماً. ما هي التصرفات الصحيحة التي يمكنك اتخاذها؟','{"options": ["تخمين الاسم الناقص وكتابة أي رقم هاتف من عندك لتكملة الخانات", "ترك خانة هذا العميل فارغة مؤقتاً ووضع علامة أو ملاحظة عليها لمراجعتها لاحقاً", "الرجوع للمشرف المسؤول أو محاولة الاتصال بالعميل إن أمكن لتعديل البيانات", "حذف الاستمارة الورقية تماماً وتجاهل إدخالها في النظام"], "correct_indices": [1, 2]}',NULL,1.0,0,'861fd86c-6517-47c8-8aab-53e7d7f935d9','2026-09-02 18:02:55.240529'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','select_all','في برنامج إكسل (Excel)، يمكنك إدخال أنواع مختلفة من البيانات في الخلايا لتنظيمها. من القائمة التالية، اختر أنواع البيانات التي يتقبلها البرنامج ويمكن إدخالها','{"options": ["النصوص والكلمات (مثل: أسماء الموظفين)", "الأرقام الصحيحة والعشرية (مثل: الرواتب أو النسب المئوية)", "التواريخ والأوقات (مثل: تاريخ التعيين أو ساعة الحضور)", "المعادلات الحسابية (مثل: =SUM لجمع الأرقام)"], "correct_indices": [0, 1, 2, 3]}',NULL,1.0,0,'f7afe996-9b14-4b6e-b393-35cb839d3a18','2026-09-02 18:04:13.932137'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','select_all','طُلب منك تنظيم وتخزين ملفات العمل اليومية على جهاز الكمبيوتر الخاص بالشركة لسهولة الوصول إليها لاحقاً. اختر الممارسات الصحيحة للتنظيم','{"options": ["إنشاء مجلدات رئيسية (Folders) ومجلدات فرعية مقسمة حسب التواريخ أو الأقسام", "تسمية الملفات بأسماء واضحة تدل على محتواها (مثل: \"تقرير مبيعات سبتمبر 2026\").", "حفظ جميع الملفات بلا استثناء على سطح المكتب (Desktop) حتى تمتلئ الشاشة", "مسح الملفات المؤقتة أو الزائدة أولاً بأول بعد التأكد من عدم الحاجة إليها"], "correct_indices": [0, 1, 3]}',NULL,1.0,0,'79c6193e-54e2-4507-8d59-936301685670','2026-09-02 18:04:53.452656');
INSERT INTO questions (job_model_id,q_type,question_text,question_data,image_path,points,order_index,id,created_at) VALUES
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','select_all','كمدخل بيانات، أنت تتعامل مع معلومات حساسة تخص موظفي وعملاء الشركة (مثل الأرقام القومية والمرتبات). اختر كل التصرفات الصحيحة للحفاظ على سرية هذه البيانات','{"options": ["قفل شاشة الكمبيوتر (Lock Win+L) دائماً عند مغادرة مكتبك ولو لدقائق معدودة", "مشاركة كلمة المرور الخاصة بحسابك مع زملائك في المكتب لمساعدتك وقت الحاجة", "عدم إرسال ملفات البيانات الشخصية عبر إيميلات خارجية غير تابعة للشركة", "إبلاغ المشرف فوراً في حال الشك بوجود اختراق أو فيروس على جهازك"], "correct_indices": [0, 1, 2, 3]}',NULL,1.0,0,'64d9cf87-13d0-48d2-943c-8fc9f95d218c','2026-09-02 18:05:35.923607'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','inline_dropdown','التعامل مع إدخال البيانات في برنامج Excel','{"template_text": "عند العمل على برنامج إكسل، نستخدم زر [drop] للانتقال إلى الخلية التالية في نفس السطر لجهة اليسار، بينما نستخدم زر [drop] للانتقال إلى الخلية التي تقع في السطر الأسفل مباشرة.", "dropdowns": [{"options": ["Tab", "Space", "Ctrl"], "correct": "2015"}, {"options": ["Shift", "Enter", "Alt"], "correct": "Enter"}]}',NULL,1.0,0,'a1029bad-6ef5-4aae-987c-e0995fd4472a','2026-09-02 18:07:37.601519'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','inline_dropdown','حفظ وتسمية ملفات العمل','{"template_text": "لحفظ ملف جديد لأول مرة في برنامج Word، نختار من قائمة ملف الأمر [drop]، ويفضل دائماً تجنب تسمية الملف بأسماء عشوائية مثل \"111\" بل يجب تسميته بـ[drop] لسهولة البحث عنه مستقبلاً.", "dropdowns": [{"options": ["فتح Open", "حفظ باسم Save As", "إغلاق Close"], "correct": "حفظ باسم Save As"}, {"options": ["اسم واضح يدل على محتواه", "تاريخ اليوم فقط", "اسم مدخل البيانات"], "correct": "التكنولوجيا"}]}',NULL,1.0,0,'4eb6295b-dd38-49b5-9358-68f494fe01a3','2026-09-02 18:09:11.875689'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','inline_dropdown','تعديل الأخطاء الإملائية أثناء الكتابة','{"template_text": "إذا قمت بكتابة كلمة خاطئة في برنامج نصوص وأردت مسح الحرف الذي يقع قبل مؤشر الكتابة مباشرة فإننا نضغط على زر [drop]، أما إذا أردنا التراجع عن آخر خطوة قمنا بها بالكامل فنضغط على اختصار [drop].", "dropdowns": [{"options": ["Delete ", "Backspace ", "Esc "], "correct": "Backspace "}, {"options": ["CTRL + Z", "CTRL + Y", "CTRL + X"], "correct": "التكنولوجيا"}]}',NULL,1.0,0,'c1fdb921-8083-4e37-bc51-47a7da7e781e','2026-09-02 18:10:55.492226'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','proofreading','أعد كتابة الفقرة التالية بشكل صحيح لتتمكن من إدخالها في نظام الشركة','{"raw_text": "أحمد موظفاً مجتهد في أقسام المبيعات، وقد قام بأرسال التقارير الي المدير العام اليوم", "corrected_text": "أحمد موظفٌ مجتهدٌ في أقسام المبيعات، وقد قام بإرسال التقارير إلى المدير العام اليوم"}',NULL,1.0,0,'9de84849-447a-4ee7-9275-7f8785bedba5','2026-09-02 18:12:17.519297'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','proofreading','أعد كتابة الجملة التالية بأسلوب سليم لتسجيلها في جدول البيانات','{"raw_text": "تم إستلام عدد خمسة وعشرون جهاز كمبيوتر جديد بتاريخ الثانى من سبتمبر ٢٠٢٦ م.", "corrected_text": "تم استلام عدد خمسة وعشرين جهاز كمبيوتر جديد بتاريخ الثاني من سبتمبر 2026م."}',NULL,1.0,0,'68eef52c-b9a3-4b4b-85c6-a392fb978079','2026-09-02 18:13:22.101117'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','proofreading','أعد كتابة العبارة التالية لتكون جاهزة للطباعة كتقرير رسمي','{"raw_text": "الرجاء من الساده الموظفين حفض ملفات العمل أول بأول في المجلد المشترك للأهميه.", "corrected_text": "الرجاء من السادة الموظفين حفظ ملفات العمل أولاً بأول في المجلد المشترك للأهمية."}',NULL,1.0,0,'8359d223-fefa-4997-be7a-ba28ca0ea5ff','2026-09-02 18:13:53.728778'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','ordering','رتّب الخطوات التالية بالترتيب الصحيح لطباعة تقرير مكتوب على برنامج Word من البداية حتى خروج الورقة من الطابعة:','{"items": ["التأكد من أن الطابعة مشغلة وتحتوي على ورق كافٍ. ", "فتح قائمة \"ملف\" واختيار أمر \"طباعة\" أو الضغط على Ctrl + P.", "تحديد عدد النسخ واختيار اسم الطابعة المتصلة بالجهاز.", "الضغط على زر \"طباعة\" النهائي."]}',NULL,1.0,0,'fc1dd358-d05c-4e30-bb6a-97eea57fb0fa','2026-09-02 18:14:49.123136'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','ordering','استلمت حزمة من الاستمارات الورقية لعملاء جدد، وتريد تفريغها في جدول إكسل. رتّب خطوات العمل التالية من الخطوة الأولى إلى الأخيرة:','{"items": ["فتح ملف إكسل جديد وكتابة عناوين الأعمدة", "البدء بنقل البيانات خطوة بخطوة من الاستمارات الورقية", "مراجعة البيانات المدخلة وتدقيقها", "حفظ الملف وتسميته باسم واضح"]}',NULL,1.0,0,'116bc439-550b-41a5-985e-6966de56a8a5','2026-09-02 18:15:27.740879'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','ordering','طُلب منك إرسال تقرير المبيعات إلى مديرك عبر البريد الإلكتروني. رتّب خطوات إعداد وإرسال الإيميل بشكل صحيح ومحترف:','{"items": ["كتابة بريد المدير في خانة المرسل إليه (To).", "كتابة عنوان واضح للإيميل في خانة الموضوع (Subject).", "كتابة تحية طيبة ونص قصير يشرح محتوى المرفق", "رفع وإرفاق ملف التقرير (Attach File) والتأكد من تحميله", "مراجعة النص المكتوب ثم الضغط على زر \"إرسال\" (Send)."]}',NULL,1.0,0,'ea601b53-4735-46f9-9877-ab6a6a11ff9c','2026-09-02 18:16:20.194773');
INSERT INTO questions (job_model_id,q_type,question_text,question_data,image_path,points,order_index,id,created_at) VALUES
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','matching','قم بمطابقة كل اختصار في القائمة (أ) مع الوظيفة الصحيحة التي يقوم بها في برامج الكتابة والإكسل في القائمة (ب):','{"pairs": [{"left": "CTRL + A", "right": "تظليل وتحديد النص بالكامل مرة واحدة"}, {"left": "CTRL + F", "right": "فتح نافذة البحث عن كلمة داخل النص"}, {"left": "CTRL + P", "right": "فتح واجهة طباعة المستند الحالي"}]}',NULL,1.0,0,'69024141-1e1e-480d-a4dd-91fcb2e09064','2026-09-02 18:17:54.716055'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','matching','صِل نوع امتداد الملف في القائمة (أ) مع البرنامج أو الصيغة المناسبة له في القائمة (ب):','{"pairs": [{"left": ".docx", "right": "مستند نصوص منسق (وورد)."}, {"left": ".xlsx", "right": "ملف بيانات وجداول (إكسل)."}, {"left": ".pdf", "right": "ملف للقراءة فقط وثابت التنسيق"}]}',NULL,1.0,0,'53fb8470-3488-48e8-b800-0e1487135183','2026-09-02 18:20:01.714864'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','matching','صِل حركة الفأرة في القائمة (أ) بالنتيجة التي تحدث في برامج الكتابة في القائمة (ب):القائمة','{"pairs": [{"left": "الضغط مرتين متتاليتين (Double Click) على كلمة", "right": "تحديد (تظليل) الكلمة التي تقف عليها فقط"}, {"left": "الضغط ثلاث مرات متتالية (Triple Click) داخل نص", "right": "تحديد الفقرة كاملة دفعة واحدة"}, {"left": "الضغط على الزر الأيمن للفأرة (Right Click)", "right": "فتح قائمة الخيارات (نسخ، لصق، تنسيق...)."}]}',NULL,1.0,0,'f0c285fb-cfbc-4d62-abb3-89171c016838','2026-09-02 18:20:52.948504'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','sjt','استلمت في بداية يومك 150 استمارة ورقية لعملاء جدد والمطلوب إدخالها بالكامل قبل نهاية الدوام (الساعة 4 عصراً). بحلول الساعة 3 عصراً، وجدت أنك أدخلت 80 استمارة فقط وتبقت 70 استمارة ومن المستحيل إنهاؤها بدقة في ساعة واحدة.','{"options": ["البدء في كتابة البيانات بسرعة فائقة جداً وبدون مراجعة لإنهائها بأي شكل قبل موعد الانصراف", "ترك الاستمارات المتبقية على مكتبك والانصراف في الموعد دون إبلاغ أحد، وإكمالها في اليوم التالي", "إبلاغ المشرف المسؤول فوراً في الساعة 3 بمعدل إنجازك، وشرح أن الكمية المتبقية تحتاج وقتاً إضافياً لضمان دقة الإدخال، وطلب توجيهه (سواء بالبقاء وقتاً إضافياً أو إكمالها غداً)."], "sjt_ratings": {"0": "ineffective", "1": "ineffective", "2": "very_effective"}}',NULL,1.0,0,'073ee8c3-d7a1-4e88-9b4a-59b957d59f11','2026-09-02 18:22:37.039009'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','sjt','طلب منك زميل لك في قسم آخر بالشركة (ليس له صلاحية الدخول على نظام الأفراد) ملف إكسل يحتوي على أرقام هواتف وعناوين الموظفين، بحجة أنه يريد تنسيقه أو يبحث عن رقم زميل له، وأكد عليك أنه صديقك ولن يخبر أحداً','{"options": ["إعطاؤه الملف فوراً على فلاشة (USB) لمساعدته كزميل في العمل وكسب وده.", "إرسال الملف له من إيميلك الشخصي حتى لا يكتشف أحد في الشركة أنك قمت بمساندته", "الرفض بأدب، وإخباره أن هذه بيانات سرية ولا تملك صلاحية مشاركتها، وتوجيهه لطلبها رسمياً من قسم الموارد البشرية أو المشرف المسؤول"], "sjt_ratings": {"0": "ineffective", "1": "ineffective", "2": "very_effective"}}',NULL,1.0,0,'e34021e8-ccea-4b98-a18d-cd7808d07aa2','2026-09-02 18:23:24.652987'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','sjt','بعد أن قمت بإدخال تقرير المبيعات الأسبوعي وحفظه وإرساله لمديرك عبر الإيميل، تنبهت فجأة وأنت تراجع مسوداتك أنك أخطأت في إدخال قيمة مبيعات أحد الفروع بزيادة صفر (كتبت 50,000 بدلاً من 5,000)، والمدير لم يرد على الإيميل بعد.','{"options": ["التغاضي عن الأمر والأمل في ألا يلاحظ المدير هذا الخطأ وسط الأرقام الكثيرة", "مسح الإيميل من جهازك وتكذيب الأمر إذا سألك المدير عن الخطأ لاحقاً", "تعديل الخطأ فوراً في ملف الإكسل، وإرسال إيميل جديد للمدير بعنوان \"تحديث: تقرير المبيعات المعدل\"، والاعتذار في نص الإيميل عن الخطأ غير المقصود في النسخة السابقة"], "sjt_ratings": {"0": "ineffective", "1": "ineffective", "2": "very_effective"}}',NULL,1.0,0,'31681b12-75b8-410a-98d6-d91bca494b9e','2026-09-02 18:23:54.427861'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','true_false_justify','يُفضل دائماً استخدام مفتاح المسطرة (Spacebar) لتنسيق وعمل مسافات كبيرة وثابتة بين الكلمات في الجداول أو المستندات الرسمية','{"correct_choice": false, "model_justification": "استخدام المسطرة لعمل مسافات كبيرة يدمر تنسيق الملف عند فتحه على أجهزة أخرى؛ والصواب هو استخدام زر Tab لعمل مسافات أفقية موحدة وثابتة، أو استخدام أدوات محاذاة النص المدمجة في البرنامج"}',NULL,1.0,0,'c5545fe1-3e99-40b6-ae68-76cfd145428c','2026-09-02 18:24:49.926709'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','true_false_justify','إذا طُلب منك إدخال بيانات من مستندات ورقية بها شطب أو تعديل غير واضح، يجب عليك تخمين الأرقام الصحيحة لتجنب تعطيل العمل.','{"correct_choice": false, "model_justification": "التخمين يؤدي إلى إدخال بيانات مغلوطة تضر بجودة النظام؛ والتصرف السليم هو التوقف عن إدخال المستند المشكوك فيه والرجوع للمشرف أو الموظف المسؤول عن كتابة المستند الأصلي لتأكيد البيانات"}',NULL,1.0,0,'531d7af9-20b0-4fb0-b42f-642e453c84e9','2026-09-02 18:25:05.554581'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','true_false_justify','يُنصح بحفظ الملفات وصادرات العمل بصيغة PDF قبل إرسالها بالبريد الإلكتروني للعملاء أو الإدارة، إذا كان الهدف هو القراءة فقط.','{"correct_choice": true, "model_justification": "لأن صيغة PDF تحافظ على التنسيق الأصلي للمستند والشكل العام كما هو، وتمنع الطرف المستلم من التعديل على البيانات أو مسحها بالخطأ، عكس ملفات الوورد أو الإكسل المفتوحة."}',NULL,1.0,0,'c2cde8bb-4574-4fdf-a825-1c500ae8ee2e','2026-09-02 18:25:23.084219'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','excel_grid','اختبار كفاءة ودقة مدخل بيانات مبتدئ في التعامل مع الجداول، واكتشاف أخطاء الإدخال والمعادلات الشائعة في برنامج Microsoft Excel وتصحيحها بناءً على المستندات الورقية الأصلية','{"instructions": "# 🔍 تمرين عملي: تدقيق ومراجعة جودة البيانات على برنامج Excel\n\nبصفتك كاتب ومدخل بيانات بالشركة، قمت بنقل بيانات موظفي الفرع الجديد من الاستمارات الورقية وتفريغها في جدول إكسل. بعد انتهائك، طُلِب منك مراجعة الجدول بدقة لأن النظام أظهر بعض التحذيرات، وتبين لك وجود أخطاء في نقل الأرقام وصياغة المعادلات وسقوط بعض البيانات.\n\n---\n\n## 💻 أولاً: الجدول الناتج في الإكسل (يحتوي على الأخطاء)\n\n| كود الموظف (ID) | اسم الموظف (Name) | الرقم القومي (National ID) | رقم الهاتف (Mobile) | الراتب الأساسي (Salary) | معادلة الحوافز (Bonus Formula) | إجمالي المستحق |\n| :--- | :--- | :--- | :--- | :--- | :--- | :--- |\n| **101** | أحمد عبد الرحمن محمد | 29508150102345 | 01023456789 | 5,000 | `=(Salary * 10%)` | 5,500 |\n| **102** | مصطفي عبدالرحمن | **29508150** *(ناقص)* | 0123456789 *(ناقص رقم)*| 4,000 | `=(Salary * 10%)` | 4,400 |\n| **103** | إبراهيم الـسـيـد | 29103200105678 | 01598765432 | **40000** *(زيادة صفر)*| `=(Salary * 10%)` | **44,000** |\n| **104** | منى أحمد علي | 29905120109876 | 01145678901 | 4,500 | `=(Salary + 10%)` *(خطأ معادلة)*| **4,510** |\n\n---\n\n## 📋 ثانياً: معطيات المستندات الورقية الأصلية (الواقع الفعلي)\n\nقبل البدء بالتعديل، راجع الشروط والملفات الورقية المستلمة من قسم الموارد البشرية:\n1. **عدد الموظفين الفعلي:** الفرع الجديد يحتوي على **5 موظفين**، وليس 4 فقط (هناك موظف سقط سهواً اسمه \"كريم حسن\").\n2. **راتب إبراهيم السيد:** الراتب الحقيقي المكتوب في عقده الورقي هو **4,000** فقط وليس 40,000.\n3. **قاعدة الحوافز:** النسبة الثابتة للحوافز هي **10% من الراتب الأساسي** وتُطبق بالضرب على جميع الموظفين دون استثناء للوصول لإجمالي المستحق.\n\n", "allowed_extensions": ".xlsx, .xls, .csv", "max_file_size_mb": 10}','/uploads/d26c1a6744114a5983464df5eba5bdf2.png',1.0,0,'a0675eb3-7da2-4995-995e-aad885882605','2026-09-02 18:30:50.106452');
INSERT INTO questions (job_model_id,q_type,question_text,question_data,image_path,points,order_index,id,created_at) VALUES
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','excel_grid','اختبار دقة الملاحظة في كشف حضور وانصراف الموظفين، واكتشاف الأخطاء الناتجة عن تكرار البيانات (Data Duplication) وتنسيق التواريخ الخاطئ في برنامج Excel بناءً على كروت الهوية الورقية','{"instructions": "# 🔍 تمرين عملي: تدقيق كشوف الحضور وتكرار البيانات في Excel\n\nبصفتك مدخل بيانات، قمت بنقل سجل الحضور اليومي للموظفين من جهاز البصمة الورقي الاحتياطي إلى جدول إكسل. بعد إرسال الجدول، تبين أن هناك تكراراً في الأسماء أدى لتضخيم عدد أيام العمل، بالإضافة لخلل في تنسيق بعض التواريخ.\n\n---\n\n## 💻 أولاً: الجدول الناتج في الإكسل (يحتوي على الأخطاء)\n\n| كود الموظف | اسم الموظف (Name) | تاريخ الحضور (Date) | الحالة (Status) | عدد الساعات |\n| :--- | :--- | :--- | :--- | :--- |\n| **201** | محمد علي حسن | 01/09/2026 | حضور | 8 |\n| **202** | سارة أحمد محمود | **مشفر/خطأ نصي** | حضور | 8 |\n| **201** | محمد علي حسن | 01/09/2026 | حضور | **8** *(سطر مكرر)* |\n| **203** | خالد وليد منير | 01/09/2026 | حضور | 8 |\n\n---\n\n## 📋 ثانياً: معطيات سجل البصمة الورقي الأصلي (الواقع الفعلي)\n\n1. **الأسماء المكررة:** الموظف \"محمد علي حسن\" (كود 201) بصم مرة واحدة فقط في هذا اليوم، لكن النظام قام بترحيل السطر مرتين بالخطأ.\n2. **تنسيق التاريخ:** التاريخ الصحيح للموظفة سارة هو **01/09/2026**، ولكن بسبب اختلاف تنسيق الخلية في الإكسل ظهرت رموز غريبة أو نص غير مفهوم.\n\n---\n", "allowed_extensions": ".xlsx, .xls, .csv", "max_file_size_mb": 10}','/uploads/84fdf76f1b6c4b47a663433df4a8c163.png',1.0,0,'1535a5a4-3e2d-441a-aa15-5cab3108ed05','2026-09-02 18:32:42.029104'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','excel_grid','اختبار مهارة مدخل البيانات في التعامل مع كشوف جرد المخازن، والتمييز بين القيمة (صفر) والخلايا الفارغة (Blank Cells)، وتصحيح معادلات الجمع التلقائي لحساب إجمالي القطع','{"instructions": "# 🔍 تمرين عملي: تدقيق كشوف جرد المخازن والمعادلات في Excel\n\nتم تكليفك بنقل بيانات \"محضر جرد المخزن الأسبوعي\" من الأوراق الرسمية إلى جدول إكسل لحساب إجمالي البضاعة المتاحة. بعد الإدخال، لاحظت أن معادلة الجمع التلقائي لا تعطي الإجمالي الصحيح بسبب ترك بعض الخانات فارغة أو خطأ في نطاق الجمع.\n\n---\n\n## 💻 أولاً: الجدول الناتج في الإكسل (يحتوي على الأخطاء)\n\n| كود الصنف | اسم المنتج (Item) | الكمية المتوفرة (Qty) | سعر القطعة | إجمالي القيمة |\n| :--- | :--- | :--- | :--- | :--- |\n| **A-10** | شاشة كمبيوتر 24 بوصة | 15 | 100 | 1,500 |\n| **A-11** | لوحة مفاتيح لاسلكية | *(تركت فارغة)* | 20 | 0 |\n| **A-12** | فأرة تحكم (ماوس) | 50 | 10 | 500 |\n| **المجموع**| **إجمالي قطع المخزن** | `=SUM(C2:C2)` *(خطأ نطاق)* | -- | **15** *(ناتج خاطئ)* |\n\n---\n\n## 📋 ثانياً: معطيات محضر الجرد الورقي الأصلي (الواقع الفعلي)\n\n1. **الكميات النافدة:** لوحة المفاتيح اللاسلكية (كود A-11) كميتها في المستند الورقي هي **(0) صفر** (نفدت الكمية تماماً)، وقام مدخل البيانات بترك الخلية فارغة تماماً بدلاً من كتابة الرقم.\n2. **معادلة المجموع:** يجب أن تحسب المعادلة إجمالي كميات كافة الأصناف الثلاثة المتواجدة في المخزن.\n", "allowed_extensions": ".xlsx, .xls, .csv", "max_file_size_mb": 10}',NULL,1.0,0,'42ac88e9-a54d-4a19-9196-b3f531f670a3','2026-09-02 18:33:24.538360'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','image_to_excel','انقل البيانات المكتوبة فى صورة الدفتر الى الاكسيل','{"instructions": "", "allowed_extensions": ".xlsx, .xls, .csv", "max_file_size_mb": 10}','/uploads/0614776c7d504e0a965f2475ffc1aa06.jpg',1.0,0,'1e5af6eb-3822-4fe8-a363-9b956ff0eb7d','2026-09-02 18:45:23.569657'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','image_to_excel','انقل البيانات المكتوبة فى صورة الدفتر الى الاكسيل','{"instructions": "", "allowed_extensions": ".xlsx, .xls, .csv", "max_file_size_mb": 10}','/uploads/1e51524eabc0436cbc986f3de6cecc11.jpg',1.0,0,'7e85256f-02f3-496d-b3d1-ea8557649710','2026-09-02 18:48:56.407535'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','image_to_excel','انقل البيانات المكتوبة فى صورة الدفتر الى الاكسيل','{"instructions": "", "allowed_extensions": ".xlsx, .xls, .csv", "max_file_size_mb": 10}','/uploads/5dce109bd038452eb70b9af0b591edcb.jpg',1.0,0,'e2b8ab26-6cf4-4898-a537-7fdb55007b71','2026-09-02 18:50:06.026000'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','summarize_word','أعد كتابة الفقرة أعلاه وتلخيصها بأسلوبك الخاص في حدود (من 30 إلى 150 كلمة)، مع الحفاظ على الأفكار الرئيسية للتقرير وبدون أخطاء إملائية.','{"reference_text": "\"بناءً على التوجيهات الصادرة من الإدارة العليا للشركة بشأن مراجعة الأداء العام لجميع الفروع خلال الربع الثاني من العام الحالي، فقد قام قسم المبيعات وتطوير الأعمال بإعداد هذا التقرير الشامل. تشير البيانات الرقمية المستخرجة من النظام السحابي إلى أن فرع القاهرة قد حقق قفزة نوعية في حجم المبيعات الإجمالية حيث بلغت نسبة النمو ما يقارب 25% مقارنة بالربع الأول من نفس العام، ويعود هذا الارتفاع الملحوظ إلى تكثيف الحملات التسويقية الرقمية عبر منصات التواصل الاجتماعي المختلفة بالإضافة إلى تقديم عروض خصومات حصرية وجاذبة للعملاء الجدد والشركات الناشئة. وعلى الجانب الآخر، واجه فرع الإسكندرية بعض التحديات التشغيلية واللوجستية التي أدت إلى تباطؤ نسبي في وتيرة العمل، حيث انخفضت مبيعاته بنسبة ضئيلة بلغت 3% بسبب تأخر وصول بعض الشحنات من الموردين الأساسيين وزيادة تكاليف الشحن الداخلي الناتجة عن تقلبات أسعار الوقود. وتوصي الإدارة المالية في نهاية هذا التقرير بضرورة اتخاذ إجراءات تصحيحية عاجلة تهدف إلى تعزيز سلاسل الإمداد في فرع الإسكندرية، والبحث عن موردين محليين بدلاء لتفادي تأخير الشحنات مستقبلاً، مع الاستمرار في دعم الاستراتيجية التسويقية الناجحة المطبقة في فرع القاهرة وتعميمها على باقي فروع الجمهورية لضمان استدامة الأرباح وتحقيق المستهدف السنوي العام للشركة قبل نهاية العام.\"", "min_words": 30, "max_words": 150}',NULL,1.0,0,'443c1379-855e-4db4-a692-8ad390cc8f3e','2026-09-02 18:51:50.595637'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','summarize_word','قم بتلخيص الفقرة السابقة بأسلوب محترف وموجز في حدود (من 30 إلى 150 كلمة) للتركيز على القواعد الأمنية الأساسية.','{"reference_text": "\"تعتبر السرية التامة وحماية البيانات الخاصة بالعملاء وبالموظفين على حد سواء الركيزة الأساسية التي تقوم عليها سياسة العمل الداخلية في شركتنا، وهي التزام قانوني وأخلاقي صارم يجب على جميع العاملين، وخاصة مدخلي البيانات وموظفي الدعم الفني، اتباعه بدقة دون أي تهاون. وتنص اللائحة التنفيذية للأمن الرقمي بالشركة على حظر مشاركة أو تسريب أي معلومات يتم التعامل معها عبر الأنظمة الداخلية، مثل الأرقام القومية، تفاصيل الرواتب، خطط الأسعار، أو أرقام الهواتف والعناوين الشخصية، مع أي جهة خارجية أو حتى مع زملاء العمل في الأقسام الأخرى الذين لا تقع هذه البيانات ضمن نطاق صلاحياتهم المباشرة. كما تلزم الإدارة كل موظف بضرورة استخدام كلمات مرور معقدة وتغييرها بصفة دورية كل ثلاثة أشهر، مع تفعيل خاصية قفل الشاشة التلقائي فور مغادرة المكتب لضمان عدم عبث أي شخص بالجهاز. وفي حال رصد أي نشاط مشبوه أو الشك في تعرض الحساب للاختراق أو الفيروسات، يتعين على الموظف إرسال بلاغ فوري عاجل إلى قسم تكنولوجيا المعلومات والرقابة الداخلية لاتخاذ التدابير التقنية اللازمة. يُعد ارتكاب أي مخالفة لهذه التعليمات بمثابة خرق جسيم لعقد العمل، ويعرض صاحبه للمساءلة القانونية والإجراءات التأديبية التي قد تصل إلى الفصل الفوري من الوظيفة والملاحقة القضائية لحماية مصالح الشركة وعملائها.\"", "min_words": 30, "max_words": 150}',NULL,1.0,0,'ab75213a-14a1-44a4-a9f4-691944f2abf5','2026-09-02 18:52:25.531893'),
	 ('b205bb40-16fd-4674-ba3b-c7421feb7ff2','summarize_word','أعد صياغة الدليل أعلاه على شكل خلاصة تنفيذية في حدود (من 30 إلى 150 كلمة).','{"reference_text": "\"إن تنظيم الأرشيف الإلكتروني وتصنيف الملفات بشكل سليم على الخوادم المشتركة للشركة يُعد الخطوة الأولى والأساسية لضمان سير العمل ب كفاءة وسرعة، وتوفير الوقت والجهد المبذول في البحث عن المستندات القديمة. يجب على موظفي الاستقبال ومدخلي البيانات اتباع آلية موحدة تعتمد على إنشاء مجلدات رئيسية لكل قسم من أقسام الشركة (مثل: الموارد البشرية، الحسابات، المشتريات)، ثم تفريع هذه المجلدات إلى مجلدات فرعية أصغر يتم ترتيبها تسلسلياً حسب السنوات والشهور. وعند حفظ أي مستند أو تقرير جديد، يُمنع تماماً استخدام الأسماء العشوائية أو الرموز المبهمة، بل يجب تسمية الملف بعبارة واضحة ومختصرة تعبر بدقة عن محتواه الداخلي وتاريخ إصداره (على سبيل المثال: فاتورة_مشتريات_أغسطس_2026). بالإضافة إلى ذلك، ينبغي على مدخل البيانات القيام بعملية فحص دورية نهاية كل أسبوع لتنظيف الأقراص الصلبة، من خلال حذف الملفات المؤقتة والمسودات المكررة التي لا قيمة لها لتوفر مساحات تخزينية جديدة ولتجنب بطء النظام التلقائي. تساعد هذه الممارسات البسيطة والمنظمة على حماية أرشيف الشركة التراكمي من الضياع، وتسهل على الإدارة والمشرفين استخراج أي تقارير أو مستندات رسمية يحتاجونها في المقابلات والاجتماعات الطارئة بسرعة ودون أي معوقات تشغيلية.\"", "min_words": 30, "max_words": 150}',NULL,1.0,0,'c4386793-71d1-46b8-a366-5b7f0e95d786','2026-09-02 18:52:56.107031'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','single_choice','طرقت باب أحد البيوت لقراءة العداد، فخرج لك صاحب البيت وكان يتحدث معك بصوت عالٍ وعصبي بسبب مشكلة قديمة في الفاتورة. ما هو التصرف البسيط والصحيح','{"options": ["أصرخ في وجهه وأتشاجر معه لأنني لست السبب في المشكلة", "أترك البيت فوراً وأجري دون أن أكلمه", "أستمع إليه بهدوء، وأقول له كلمات طيبة مثل \"حاضر يا فندم\"، وأطلب منه قراءة العداد بكل أدب", "أهدده بقطع الخدمة عن منزله فوراً"], "correct_indices": [2]}',NULL,1.0,0,'baad7440-527f-4edb-8523-a3ef12f97636','2026-09-02 19:01:39.621183'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','multiple_choice','قبل أن تبدأ جولتك اليومية في الشارع لقراءة العدادات وتحصيل الفواتير، ما هي الأشياء والأدوات الضرورية التي يجب أن تتأكد من وجودها معك؟','{"options": ["دفاتر الفواتير والإيصالات الرسمية الخاصة بالشركة", "وجبة غداء كبيرة وصحف يومية لقراءتها أثناء العمل", "أقلام للكتابة وجهاز التحصيل أو الهاتف المشحون بالكامل", "مبالغ مالية صغيرة (فكة) لرد باقي الفلوس للمواطنين بسهولة."], "correct_indices": [0, 2, 3]}',NULL,1.0,0,'8093c18e-23b3-4dbe-8ff1-a0ea5a6762d5','2026-09-02 19:03:26.303011');
INSERT INTO questions (job_model_id,q_type,question_text,question_data,image_path,points,order_index,id,created_at) VALUES
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','multiple_choice','أثناء قيامك بجمع أموال الفواتير من المواطنين في الشارع، ما هي الخطوات التي يجب عليك اتباعها للحفاظ على هذه الأموال حتى تسليمها للشركة؟','{"options": ["وضع النقود فوراً داخل الحقيبة المخصصة للتحصيل وإغلاقها جيداً", "ترك الأموال في جيوبك أو في يدك أثناء السير بين البيوت", "مراجعة إجمالي المبالغ مع كعوب الفواتير بشكل دوري خلال اليوم", "إقراض أحد الزملاء جزءاً من الأموال على أن يردها لك نهاية اليوم"], "correct_indices": [2, 0]}',NULL,1.0,0,'cea9a50e-7f44-4617-abe3-61050542055f','2026-09-02 19:04:10.271175'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','multiple_choice','إذا وقفت أمام عداد ووجدت زجاج الشاشة متسخاً جداً أو مغطى بالأتربة، والأنوار خافتة مما يجعل الأرقام غير واضحة تماماً. ما هي التصرفات السليمة التي يمكنك فعلها','{"options": ["مسح زجاج العداد بقطعة قماش أو منديل لتنظيفه ورؤية الأرقام", "تخمين أرقام  وكتابتها في الدفتر", "استخدام كشاف الهاتف أو الإضاءة الخارجية لتوضيح الأرقام المخفية", "مغادرة المكان فوراً وكتابة \"العداد مكسور\" دون محاولة التأكد"], "correct_indices": [0, 2]}',NULL,1.0,0,'ae6b8672-87e0-4053-b44d-aede807944fb','2026-09-02 19:04:55.304861'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','select_all','عندما تسلم العميل فاتورته وتطلب منه قيمة الاستهلاك، ما هي البيانات التي يجب أن تظهر بوضوح في الفاتورة أو الإيصال الرسمي؟','{"options": ["اسم المستهلك (صاحب العداد) وعنوانه بالكامل", "قيمة المبلغ المطلوب سداده بوضوح بالأرقام والحروف", "فترة الاستهلاك (الشهر والسنة).", "شعار الشركة الرسمي وختمها أو الرقم المتسلسل للإيصال"], "correct_indices": [0, 1, 2, 3]}',NULL,1.0,0,'cccd1b39-53d2-4dc5-a409-3ce1fbae2036','2026-09-02 19:05:46.991880'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','select_all','أثناء جولتك في الشوارع لزيارة المنازل وقراءة العدادات، ما هي السلوكيات والقواعد التي يجب عليك الالتزام بها؟','{"options": ["ارتداء الزي الرسمي للشركة (الـ Uniform) وحمل بطاقة الهوية الوظيفية (الـ ID) بشكل ظاهر", "التعامل بأدب واحترام مع جميع المواطنين حتى لو واجهت معاملة جافة", "الالتزام بخط السير والمناطق المحددة لك من قبل المشرف دون تغيير عشوائي", "الدخول إلى الأماكن الخاصة أو المغلقة داخل المنازل دون استئذان أصحابها"], "correct_indices": [0, 1, 2]}',NULL,1.0,0,'4ca08d95-514c-4979-9d60-a0cb8307e5f1','2026-09-02 19:06:23.912734'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','select_all','أثناء قراءتك للعدادات في منطقتك، ما هي المواقف غير الطبيعية التي إذا رأيتها يجب عليك تصويرها وإبلاغ المشرف عنها فوراً؟','{"options": ["وجود كسر في زجاج العداد أو تلف واضح في هيكله الخارجي", "ملاحظة وجود توصيلات غير قانونية (سرقة خلف العداد) لتشغيل الخدمة بدون علم الشركة", "وجود كسر أو تلاعب في الأختام الرصاصية الأمنية الموضوعة على العداد", "تغيير المستهلك للغرفة التي يقع بها العداد"], "correct_indices": [0, 1, 2]}',NULL,1.0,0,'7fedf0ec-8fe3-4b5f-acce-c301c2498df8','2026-09-02 19:07:09.237478'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','inline_dropdown','طريقة التعامل عند قراءة العداد','{"template_text": "عند وصولك إلى منزل المشترك، يجب عليك أولاً [drop] وأخذ الإذن قبل الدخول، وعند تسجيل القراءة تتأكد من نقل الأرقام [drop] الموجودة في شاشة العداد لضمان دقة الفاتورة.", "dropdowns": [{"options": ["طرق الباب بلطف", "الدخول فوراً", "النداء بصوت عالٍ"], "correct": "2015"}, {"options": ["الحقيقية الحالية", "التقريبية المتوقعة", "القديمة المكتوبة"], "correct": "التكنولوجيا"}]}',NULL,1.0,0,'fd310127-b3be-4f09-a651-0e47ec73e186','2026-09-02 19:08:54.278484'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','inline_dropdown','تسليم الأموال والفواتير للشركة','{"template_text": "بعد انتهاء جولة التحصيل اليومية، يتوجه الموظف إلى قسم الخزينة لتسليم [drop] التي جمعها من المواطنين، ويقوم بمطابقتها مع [drop] الفواتير المتبقية معه لضمان عدم وجود عجز مالي.", "dropdowns": [{"options": ["الأموال النقدية", "الأوراق البيضاء", "العهدة الشخصية"], "correct": "2015"}, {"options": ["كعوب وإيصالات", "أسماء وأقارب", "أرقام هواتف"], "correct": "التكنولوجيا"}]}',NULL,1.0,0,'829326b7-eeb4-4061-9a3a-8a981c2340e0','2026-09-02 19:09:57.265073'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','inline_dropdown','التعامل مع الأعطال والمخالفات','{"template_text": "إذا لاحظت أثناء العمل وجود عداد متوقف تماماً عن الدوران رغم استهلاك المواطن، فإنك تسجل حالة العداد [drop] في دفترك، وتتجنب تماماً [drop] القراءة من عندك حتى لا تقع في مسؤولية قانونية.", "dropdowns": [{"options": ["عاطل / متوقف", "سليم ويعمل", "جديد "], "correct": "عاطل / متوقف"}, {"options": ["تخمين وكتابة", "تصوير ومسح", "مراجعة وتدقيق"], "correct": "التكنولوجيا"}]}',NULL,1.0,0,'961d68c7-b2a4-4b98-970d-1dbfc92c5f41','2026-09-02 19:32:44.127354'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','proofreading','أعد كتابة الجملة التالية بشكل صحيح لتسجيلها في دفتر تقارير الحضور والميدان','{"raw_text": "أستلم المحصل عهدة الفواتير اليوم صباحاً وقام بزيارة خمسون شقة في المنطقة", "corrected_text": "استلم المحصل عهدة الفواتير اليوم صباحاً وقام بزيارة خمسين شقة في المنطقة"}',NULL,1.0,0,'74b64d22-c89c-4cf4-800c-ba54cf584eea','2026-09-02 19:33:29.875298'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','proofreading','أعد كتابة العبارة التالية لتكون خالية من الأخطاء عند تقديمها للمشرف','{"raw_text": "تم قراءة العداد بنجاح ولاكن وجدنا تسريب مياه بجوار المحبس الرئبسي", "corrected_text": "تمت قراءة العداد بنجاح ولكن وجدنا تسريب مياه بجوار المحبس الرئيسي"}',NULL,1.0,0,'ccb9db8b-2ddd-43c4-9580-1b3621226ed5','2026-09-02 19:33:50.918926');
INSERT INTO questions (job_model_id,q_type,question_text,question_data,image_path,points,order_index,id,created_at) VALUES
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','proofreading','أعد كتابة العبارة الآتية لتصحيح الأخطاء قبل إدخالها في سجل المخالفات','{"raw_text": "المواطن يرفض السداد بحجة ان الفاتورة مرتفعة جداً وطالب بئعادة الفحص", "corrected_text": "المواطن يرفض السداد بحجة أن الفاتورة مرتفعة جداً وطالب بإعادة الفحص"}',NULL,1.0,0,'d29e27ac-6c7f-4d3d-920a-4c08ff94ecee','2026-09-02 19:34:18.113238'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','ordering','رتّب الخطوات التالية بالترتيب الصحيح الذي يجب أن تتبعه عند وصولك إلى العقار المحدد لقراءة العداد','{"items": ["طرق باب الشقة أو مدخل العقار بلطف والانتظار حتى يفتح صاحب البيت", "إلقاء التحية على المشترك والتعريف بنفسك وإبراز بطاقتك الوظيفية (ID).", "التوجه إلى مكان العداد المحدّد ونقل أرقام الاستهلاك الحالية بدقة في دفترك", "مراجعة القراءة المسجلة بسرعة للتأكد من منطقيتها ومطابقتها لشاشة العداد قبل التحرك"]}',NULL,1.0,0,'48d3a156-1ac6-4474-a3bd-666cd648d759','2026-09-02 19:35:11.347445'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','ordering','عندما يوافق المشترك على سداد الفاتورة نقداً في الشارع، رتّب خطوات عملية التحصيل والتقفيل المالية من الخطوة الأولى إلى الأخيرة:','{"items": ["إخراج دفتر الفواتير والبحث عن اسم المشترك والتأكد من قيمة المبلغ المطلوب", "استلام المبلغ النقدي من العميل وعده يدوياً بتركيز أمامه للتأكد من صحته.", "تمزيق الفاتورة الرسمية (أو إيصال السداد) وتسليمها للمواطن مع رد الباقي (الفكة) له إن وُجد.", "وضع الأموال النقدية فوراً داخل حقيبة التحصيل المخصصة وتأمينها."]}',NULL,1.0,0,'3ce6df4f-1ad1-4f76-8bbd-060ca5e4516a','2026-09-02 19:35:52.950215'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','ordering','بعد انتهاء جولاتك الميدانية والعودة لمقر الشركة، رتّب خطوات إنهاء عملك وتسليم العهدة بشكل صحيح وقانوني','{"items": ["عد المبالغ النقدية الموجودة بحقيبتك يدوياً في مكان هادئ وتجميع إجمالي المبلغ المحصل", "مطابقة إجمالي الفلوس النقدية مع مجموع كعوب الفواتير التي قمت بتحصيلها للتأكد من عدم وجود عجز", "تسليم المبالغ النقدية كاملة لأمين الخزينة واستلام إيصال توريد رسمي منه", "تسليم الفواتير المتبقية (غير المحصلة) لقسم الحسابات لإثبات حالة عدم السداد وتصفير العهدة"]}',NULL,1.0,0,'abbb52f6-deb0-4388-b75a-85b6be031fed','2026-09-02 19:36:33.490974'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','matching','قم بمطابقة نوع العداد في القائمة (أ) مع طريقة قراءته الصحيحة في القائمة (ب):','{"pairs": [{"left": "العداد الميكانيكي القديم (بأرقام تدور)", "right": "ننقل الأرقام السوداء الصحيحة فقط من اليمين إلى اليسار ونتجاهل الكسور الحمراء"}, {"left": "العداد الإلكتروني الحديث (بشاشة ديجيتال)", "right": "نضغط على الزر البلاستيكي لتنقل الشاشة بين (الاستهلاك الكلي، الرصيد المتبقي)."}, {"left": "العداد الذكي مسبق الدفع (بالكارت)", "right": "لا نقرأ منه أرقاماً بل نمرر عليه كارت الشحن لتحديث البيانات في النظام."}]}',NULL,1.0,0,'fe47263e-8022-457b-b375-d0fce7c06e5c','2026-09-02 19:39:10.582334'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','matching','صِل موقف المستهلك في القائمة (أ) مع الإجراء الفوري الصحيح الذي يجب أن يتخذه المحصل في القائمة (ب):','{"pairs": [{"left": "وافق على السداد وأعطاك كامل المبلغ النقدي", "right": "نمزق الفاتورة الأصلية ونسلمها له فوراً مع رد الباقي (الفكة)"}, {"left": "رفض السداد تماماً واعتذر لعدم توفر أموال معه", "right": "نعيد الفاتورة كما هي للشركة ملتصقة بكعبها ونسجل في النظام \"مؤجل/رفض\"."}, {"left": "الشقة مغلقة بالكامل ولا يوجد أحد بالداخل", "right": "نترك له إشعاراً ورقياً رسمياً بمرورنا ونكتب في النظام \"مغلق\"."}]}',NULL,1.0,0,'99f3f1d4-0810-43a2-8131-b3df5356d2c5','2026-09-02 19:39:59.265479'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','matching','صِل المشكلة الملاحظة على العداد في القائمة (أ) بـالوصف الصحيح الذي ستكتبه في تقريرك للمشرف في القائمة (ب):','{"pairs": [{"left": "شاشة العداد مكسورة تماماً والزجاج مهشم", "right": "عداد تالف / غير واضح القراءة"}, {"left": "أرقام العداد ثابتة لا تتحرك رغم تشغيل الأجهزة", "right": "عداد متوقف / عاطل عن العمل."}, {"left": "وجود سلك خارجي يتخطى العداد لتشغيل الشقة", "right": "شبهة توصيل غير قانوني (سرقة)."}]}',NULL,1.0,0,'5d94a5f1-95b7-4add-b378-e47f3466f827','2026-09-02 19:40:40.933500'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','sjt','طرقت باب أحد المواطنين لتحصيل الفاتورة، فخرج لك غاضباً جداً ويصرخ بصوت عالٍ قائلاً: "الشركة حرامية والفاتورة قيمتها ضعف الشهر الماضي ولن أدفع جنيهاً واحداً!" والناس في الشارع بدأت تتجمع حولكما','{"options": ["أصرخ في وجهه وأقول له: \"احترم نفسك وإلا سأقطع عنك الخدمة فوراً وأبلغ الشرطة\".", "آخذ الفاتورة منه وأقاطعه تماماً وأغادر العمارة دون أن أنطق بكلمة واحدة.", "أستمع إليه بهدوء تماماً دون مقاطعة حتى يفرغ غضبه، ثم أقول له بلطف: \"حقك عليّ يا فندم، دعنا نراجع أرقام العداد معاً الآن للتأكد من عدم وجود خطأ، وإذا تبين وجود مشكلة سأكتب لك طلباً رسمياً لإعادة الفحص بالمقر"], "sjt_ratings": {"0": "ineffective", "1": "ineffective", "2": "very_effective"}}',NULL,1.0,0,'7524c875-b43d-4e3e-b216-e4e84b412b73','2026-09-02 19:41:41.331317'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','sjt','ذهبت لتحصيل فاتورة قيمتها 400 جنيه من سيدة مسنة، فقالت لك باكية إن أموالها لا تكفي هذا الشهر وتعطيك 200 جنيه فقط وتطلب منك تمزيق الفاتورة وإعطائها لها على أن تسدد الباقي الشهر القادم','{"options": ["أتعاطف معها وأمزق لها الفاتورة وآخذ الـ 200 جنيه وأدفع الباقي من جيبي الخاص كصدقة", "أرفض كلامها بحدة وآخذ الفاتورة وأقول لها: \"طالما لا تملكين المال سأسجل في النظام أنك تتهربين من السداد\".", "أشرح لها بأسلوب مهذب ورقرق أن نظام الماكينة أو الدفتر لا يتقبل تقسيط الفاتورة الواحدة أو تمزيقها مجزأة، وأقترح عليها إرجاء السداد كاملاً لبضعة أيام أو التوجه لفرع الشركة لطلب جدولة المديونية رسمياً."], "sjt_ratings": {"0": "ineffective", "1": "ineffective", "2": "very_effective"}}',NULL,1.0,0,'1d8efa9f-68cf-4838-8a23-a863405d917f','2026-09-02 19:42:18.258599'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','sjt','أثناء قراءتك لعداد في محل تجاري كبير، لاحظت أن استهلاكه مرتفع جداً وسيدخل في شريحة غالية، فطلب منك صاحب المحل أن تسجل في دفترك قراءة منخفضة (أقل من الحقيقة) وعرض عليك مبلغ 200 جنيه كـ "إكرامية أو شاي" مقابل مساعدته.','{"options": ["أوافق فوراً وآخذ المبلغ وأسجل القراءة المنخفضة طالما أن أحداً لا يرانى في الشارع", "أرفض العرض تماماً بقطع وحسم، وأقول له: \"أنا أقوم بعملي بأمانة يا فندم ولا أقبل ذلك\"، ثم أسجل القراءة الحقيقية الفعلية كاملة فوراً على النظام دون زيادة أو نقصان", "أخذ المبلغ منه ثم أقوم بتسجيل القراءة الحقيقية دون علمه لأخدع صاحب المحل."], "sjt_ratings": {"0": "ineffective", "1": "very_effective", "2": "ineffective"}}',NULL,1.0,0,'4ed73d24-604c-49cd-80e8-964e96f9ba9f','2026-09-02 19:42:53.478665');
INSERT INTO questions (job_model_id,q_type,question_text,question_data,image_path,points,order_index,id,created_at) VALUES
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','true_false_justify','يُسمح للمحصل بتمزيق وتسليم الفاتورة للعميل إذا وعده العميل شفهياً بسداد المبلغ في اليوم التالي','{"correct_choice": false, "model_justification": "لا يجوز تسليم الفاتورة الرسمية إلا بعد استلام كامل قيمتها نقداً؛ لأن تسليم الفاتورة يُعتبر إبراء ذمة للعميل، ويضع المحصل تحت مسؤولية وجود عجز مالي في عهدته."}',NULL,1.0,0,'1f3099e4-acb8-49b3-84c5-ebb148fe8cba','2026-09-02 19:43:22.083736'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','true_false_justify','إذا وجد قارئ العدادات أن أحد المشتركين قد قام بكسر قفل العداد لتوصيل الخدمة مباشرة، يجب عليه مشاجرة العميل في الشارع فوراً.','{"correct_choice": false, "model_justification": "ليس من مهام القارئ الدخول في مشاجرات مع المواطنين؛ بل يجب عليه إثبات المخالفة وتصويرها بهدوء، ثم رفع تقرير فوري للمشرف لاتخاذ الإجراءات القانونية عبر شرطة الشركة"}',NULL,1.0,0,'cb26193e-cc2e-47a6-882f-8e09b903db35','2026-09-02 19:43:41.395163'),
	 ('9b9b4b08-e85c-404b-b97c-8953fb825c7c','true_false_justify','يُفضل دائماً تدوين ملاحظة "العداد مغلق" في حال عدم تواجد العميل بالمنزل بدلاً من تخمين أي أرقام من عندك.','{"correct_choice": true, "model_justification": "لأن الأمانة تقتضي إثبات الواقع الفعلي، وتخمين القراءات يسبب مشاكل وفواتير عشوائية تضر بالشركة وتؤدي إلى شكاوى قانونية من المشتركين"}',NULL,1.0,0,'a9ea63a3-faac-4b9a-b1b3-f8b2d68e1669','2026-09-02 19:44:02.372352');
